CREATE TABLE raising_profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), fly_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at INTEGER NOT NULL, loadout_json TEXT NOT NULL);
CREATE TABLE raising_catalog (id TEXT PRIMARY KEY, slot TEXT NOT NULL, name TEXT NOT NULL, cost INTEGER NOT NULL CHECK(cost>=0));
INSERT INTO raising_catalog VALUES ('head-cap','head','Cap',0),('head-crown','head','Crown',50),('head-beanie','head','Beanie',25),('face-glasses','face','Glasses',0),('face-monocle','face','Monocle',50),('face-visor','face','Visor',25),('body-tie','body','Tie',0),('body-bowtie','body','Bow tie',25),('body-vest','body','Vest',50),('background-mint','background','Mint',0),('background-rose','background','Rose',25),('background-graphite','background','Graphite',50);
CREATE TABLE raising_points (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), amount INTEGER NOT NULL, kind TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TRIGGER raising_points_update BEFORE UPDATE ON raising_points BEGIN SELECT RAISE(ABORT,'immutable points'); END;
CREATE TRIGGER raising_points_delete BEFORE DELETE ON raising_points BEGIN SELECT RAISE(ABORT,'immutable points'); END;
CREATE TABLE raising_ownership (user_id TEXT NOT NULL REFERENCES users(id), item_id TEXT NOT NULL REFERENCES raising_catalog(id), created_at INTEGER NOT NULL, PRIMARY KEY(user_id,item_id));
CREATE TRIGGER raising_purchase_balance BEFORE INSERT ON raising_ownership WHEN NOT EXISTS(SELECT 1 FROM raising_ownership WHERE user_id=NEW.user_id AND item_id=NEW.item_id) BEGIN SELECT CASE WHEN (SELECT cost FROM raising_catalog WHERE id=NEW.item_id)>COALESCE((SELECT SUM(amount) FROM raising_points WHERE user_id=NEW.user_id),0) THEN RAISE(ABORT,'INSUFFICIENT_POINTS') END; END;
CREATE TRIGGER raising_purchase_debit AFTER INSERT ON raising_ownership WHEN (SELECT cost FROM raising_catalog WHERE id=NEW.item_id)>0 BEGIN INSERT INTO raising_points VALUES ('purchase:'||NEW.user_id||':'||NEW.item_id,NEW.user_id,-(SELECT cost FROM raising_catalog WHERE id=NEW.item_id),'PURCHASE',NEW.created_at); END;
CREATE TABLE raising_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, created_at INTEGER NOT NULL, completed_at INTEGER, step INTEGER NOT NULL DEFAULT 0, symbol TEXT NOT NULL, scenario_family TEXT NOT NULL, reward_points INTEGER NOT NULL DEFAULT 0, reward_eligible INTEGER NOT NULL DEFAULT 0, data_json TEXT NOT NULL, state_json TEXT NOT NULL, action_token TEXT);
CREATE UNIQUE INDEX raising_one_active ON raising_sessions(user_id) WHERE status='ACTIVE';
CREATE TABLE raising_reservations (user_id TEXT NOT NULL REFERENCES users(id), scenario_family TEXT NOT NULL, session_id TEXT NOT NULL REFERENCES raising_sessions(id), day TEXT NOT NULL, PRIMARY KEY(user_id,scenario_family));
CREATE TABLE raising_demonstrations (session_id TEXT NOT NULL REFERENCES raising_sessions(id), step INTEGER NOT NULL, idempotency_key TEXT NOT NULL, body_json TEXT NOT NULL, record_json TEXT NOT NULL, PRIMARY KEY(session_id,step), UNIQUE(session_id,idempotency_key));
CREATE TABLE raising_system_actions (session_id TEXT NOT NULL REFERENCES raising_sessions(id), step INTEGER NOT NULL, record_json TEXT NOT NULL, PRIMARY KEY(session_id,step));
CREATE TRIGGER raising_demo_update BEFORE UPDATE ON raising_demonstrations BEGIN SELECT RAISE(ABORT,'immutable demonstration'); END;
CREATE TRIGGER raising_demo_delete BEFORE DELETE ON raising_demonstrations BEGIN SELECT RAISE(ABORT,'immutable demonstration'); END;
CREATE TRIGGER raising_system_update BEFORE UPDATE ON raising_system_actions BEGIN SELECT RAISE(ABORT,'immutable system action'); END;
CREATE TRIGGER raising_system_delete BEFORE DELETE ON raising_system_actions BEGIN SELECT RAISE(ABORT,'immutable system action'); END;
